    "vitest": "^4.1.5"
  }
}

--- Cargo ---
[package]
name = "dam-hopper-native"
version = "0.1.0"
description = "DamHopper native client"
authors = ["DamHopper contributors"]
edition = "2021"

[lib]
name = "dam_hopper_native_lib"
crate-type = ["staticlib", "cdylib", "rlib"]

[build-dependencies]
tauri-build = { version = "=2.6.3", features = [] }

[dev-dependencies]
tauri = { version = "=2.11.5", features = ["test"] }

[dependencies]
serde = { version = "1", features = ["derive"] }
serde_json = "1"
getrandom = "0.3.4"
sha2 = "0.10"
url = "2.5"
tauri = { version = "=2.11.5", features = ["unstable"] }
time = { version = "=0.3.47", features = ["formatting", "macros", "parsing"] }
toml = "=0.8.2"
uuid = { version = "=1.23.1", features = ["serde", "v4"] }

[target.'cfg(windows)'.dependencies]
base64 = "=0.22.1"
webview2-com = "=0.38.2"
windows = { version = "0.61", features = ["Win32_Foundation"] }
windows-sys = { version = "0.61", features = ["Wdk_Foundation", "Wdk_Storage_FileSystem", "Win32_Foundation", "Win32_Security", "Win32_Storage_FileSystem", "Win32_System_IO", "Win32_System_Threading"] }
russh = { version = "=0.62.5", default-features = false, features = ["ring"] }
tokio = { version = "1", features = ["io-util", "macros", "net", "rt", "sync", "time"] }

[target.'cfg(any(target_os = "windows", target_os = "macos", target_os = "linux"))'.dependencies]

[workspace]

