    40	    #[allow(dead_code)]
    41	    pub(crate) fn is_disposed(&self) -> bool {
    42	        self.state.load(Ordering::Acquire) == DISPOSED
    43	    }
    44	
    45	    pub(crate) fn should_prevent_exit(&self) -> bool {
    46	        self.state.load(Ordering::Acquire) != DISPOSED
    47	    }
    48	
    49	    pub(crate) fn begin_disposal(&self) -> bool {
    50	        self.state
    51	            .compare_exchange(RUNNING, DISPOSING, Ordering::AcqRel, Ordering::Acquire)
    52	            .is_ok()
    53	    }
    54	
    55	    pub(crate) fn trigger<R: Runtime>(self: &Arc<Self>, app: AppHandle<R>) {
    56	        if !self.begin_disposal() {
    57	            return;
    58	        }
    59	        let coordinator = Arc::clone(self);
    60	        tauri::async_runtime::spawn(async move {
    61	            coordinator.dispose_resources(&app).await;
    62	            app.exit(0);
    63	        });
    64	    }
    65	
    66	    async fn dispose_resources<R: Runtime>(&self, app: &AppHandle<R>) {
    67	        let deadline = Instant::now() + SHUTDOWN_GRACE;
    68	        let manager = Arc::clone(&self.manager);
    69	        let browser_debug = Arc::clone(&self.browser_debug);
    70	        let cleanup_app = app.clone();
    71	        let cleanup = tauri::async_runtime::spawn_blocking(move || {
    72	            browser_debug.cleanup_on_main_close(&cleanup_app);
    73	        });
    74	        let manager_dispose = async {
    75	            let remaining = deadline.saturating_duration_since(Instant::now());
    76	            let _ = tokio::time::timeout(remaining, manager.dispose()).await;
    77	        };
    78	        let browser_cleanup = async {
    79	            let remaining = deadline.saturating_duration_since(Instant::now());
    80	            let _ = tokio::time::timeout(remaining, cleanup).await;
    81	        };
    82	        tokio::join!(manager_dispose, browser_cleanup);
    83	        self.manager.force_close();
    84	        self.state.store(DISPOSED, Ordering::Release);
    85	    }
    86	
    87	    pub(crate) fn force_close_now(&self) {
    88	        self.manager.force_close();
    89	        self.state.store(DISPOSED, Ordering::Release);
    90	    }
    91	}
